            public void InitializeCipher(byte[] key)
            {
                BlowfishKey = key;
                EncryptEngine = new BlowfishEngine();
                DecryptEngine = new BlowfishEngine();
                EncryptEngine.Init(true, new KeyParameter(key));
                DecryptEngine.Init(false, new KeyParameter(key));
            }
        }

