            {
                _playerStates[connId] = new PlayerState();
            }
            return _playerStates[connId];
        }

        private static bool IsPassiveSkill(string skillGcClass)
        {
            if (string.IsNullOrEmpty(skillGcClass)) return false;
            string lower = skillGcClass.ToLowerInvariant();
            return lower.Contains("passive") || lower.Contains("trait");
        }

        private static bool TryGetClassPassiveForSkill(string skillGcClass, out string className, out ClassPassive passive)
        {
            className = null;
            passive = null;
            if (string.IsNullOrEmpty(skillGcClass)) return false;
            foreach (var kvp in ClassPassiveData.Passives)
            {
                if (string.Equals(kvp.Value.PassiveSkillId, skillGcClass, StringComparison.OrdinalIgnoreCase))
                {
                    className = kvp.Key;
                    passive = kvp.Value;
                    return true;
                }
            }
            return false;
        }

        private static int CalculateClassPassiveManaBonusWire(ClassPassive passive)
        {
            if (passive == null) return 0;
            double baseIntellect = ClassPassiveData.BASE_INTELLECT;
            double effectiveIntellect = Math.Max(1, baseIntellect + passive.IntellectMod);
            double baseMana = baseIntellect * 17.0;
            double passiveMana = effectiveIntellect * 17.0 * (100.0 + passive.ManaPerIntellectMod) / 100.0;
            return (int)Math.Round((passiveMana - baseMana) * 256.0);
        }

        private static int GetPassiveHealthModPercent(string skillGcClass)
        {
            if (string.Equals(skillGcClass, "skills.generic.MeleeAttackRatingModPassive", StringComparison.OrdinalIgnoreCase))
                return -20;
            return 0;
        }

        private void RecalculateHotbarPassiveBonuses(string connId)
        {
            RRConnection conn = _connections.Values.FirstOrDefault(c => c.ConnId.ToString() == connId);
            if (conn == null || conn.LoginName == null || !_selectedCharacter.ContainsKey(conn.LoginName))
            {
                GetPlayerState(connId).SetPassiveBonuses(0, 0);
                return;
            }

            SavedCharacter savedChar = CharacterRepository.GetCharacter(_selectedCharacter[conn.LoginName].Id);
            RecalculateHotbarPassiveBonuses(conn, savedChar);
        }

        private void RecalculateHotbarPassiveBonuses(RRConnection conn, SavedCharacter savedChar)
        {
            if (conn == null) return;

            PlayerState playerState = GetPlayerState(conn.ConnId.ToString());
            int hpWireBonus = 0;
            int manaWireBonus = 0;
            int healthPercentMod = 0;
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (savedChar?.hotbarSlots != null)
            {
                foreach (var hbs in savedChar.hotbarSlots)
                {
                    if (string.IsNullOrEmpty(hbs.skill) || !IsPassiveSkill(hbs.skill) || !seen.Add(hbs.skill))
                        continue;

                    if (TryGetClassPassiveForSkill(hbs.skill, out string className, out ClassPassive passive))
                    {
                        hpWireBonus += ClassPassiveData.CalculateHPBonusWire(className);
                        manaWireBonus += CalculateClassPassiveManaBonusWire(passive);
                    }

                    healthPercentMod += GetPassiveHealthModPercent(hbs.skill);
                }
            }

            if (healthPercentMod != 0)
                hpWireBonus += (int)Math.Round(((long)playerState.MaxHPWireWithoutPassives + hpWireBonus) * (healthPercentMod / 100.0));

            playerState.SetPassiveBonuses(hpWireBonus, manaWireBonus);
            Debug.LogError($"[PASSIVE-STATS] {conn.LoginName}: HP passive {hpWireBonus} wire, Mana passive {manaWireBonus} wire");
        }

        /// <summary>
        /// Calculate modifier HP bonus based on armor type's Rare.Mod2 definition.
        /// From GC Files analysis:
        /// - PlateModPAL.Rare.Mod2 = MaxHitPointB_MaxManaB (Value=0.5) → 376 wire at L50
        /// - CrystalModPAL.Rare.Mod2 = MaxHitPointB (Value=1.0) → 752 wire at L50
        /// - ChainModPAL.Rare.Mod2 = DivineDamageResistB_IceDamageResistB → 0 HP
        /// - ScaleModPAL.Rare.Mod2 = MaxManaB → 0 HP
        /// - LeatherModPAL.Rare.Mod2 = RangeAttackSpeedM → 0 HP
        /// </summary>
        private uint GetModifierHPBonus(string gcClass, int playerLevel)
        {
            string gcLower = gcClass.ToLower();
            int itemLevel = playerLevel + 3;
            int maxPool = 50 + (itemLevel - 1) * 7950 / 109;

            if (gcLower.StartsWith("plate") || gcLower.StartsWith("chain"))
            {
                return (uint)(maxPool * 0.5);
            }
            else if (gcLower.StartsWith("crystal"))
            {
                return (uint)maxPool;
            }
            return 0;
        }
        /// Calculate equipment HP bonuses from equipped items
        /// </summary>
        // REPLACE your existing CalculateEquipmentBonuses method with this one
        private (int hp, int endurance, int modifierHP) CalculateItemBonuses(string gcClass, int playerLevel, bool isMythic)
        {
            if (!isMythic)
                return (0, 0, 0);

            int itemLevel = playerLevel + 3;

            int maxPool = 50 + (itemLevel - 1) * 7950 / 109;
            Debug.LogError($"[HP-CALC] playerLevel={playerLevel}, itemLevel={itemLevel}, maxPool={maxPool}");
            string gcLower = gcClass.ToLower();

            // Check armor type
            bool isPlate = gcLower.Contains("platemythic") || gcLower.Contains("plateunique");
            bool isChain = gcLower.Contains("chainmythic") || gcLower.Contains("chainunique");
            bool isCrystal = gcLower.Contains("crystalmythic") || gcLower.Contains("crystalunique");
            bool isLeather = gcLower.Contains("leathermythic") || gcLower.Contains("leatherunique");
            bool isScale = gcLower.Contains("scalemythic") || gcLower.Contains("scaleunique");
            bool isSplint = gcLower.Contains("splintmythic") || gcLower.Contains("splintunique");
            // Check if item has MaxHitPointB modifier
            bool hasMaxHitPointB = gcLower.Contains("helm1") || gcLower.Contains("helm5") ||
                         gcLower.Contains("armor3") ||
                         gcLower.Contains("gloves3") || gcLower.Contains("gloves5") ||
                         (isPlate && (gcLower.Contains("shoulders1") || gcLower.Contains("shoulders3") || gcLower.Contains("shoulders5"))) ||
                         (isChain && !gcLower.Contains("shield"));

            // Check if item has AgilityB instead of EnduranceB (gives 0 endurance)
            bool hasAgilityNotEndurance = gcLower.Contains("helm3") || gcLower.Contains("helm6") || gcLower.Contains("helm7") ||
                                           gcLower.Contains("gloves3") || gcLower.Contains("gloves5") ||
                                           (gcLower.Contains("shoulders") && !((isPlate && gcLower.Contains("shoulders1")) || isChain || isCrystal || isSplint));

            //GLOVES - Crystal and Splint both have 0.8 End, NO HP
            if (gcLower.Contains("glove") || gcLower.Contains("gaunt"))
            {
                int slotPool = maxPool / 20;
                int hp = slotPool * 537 / 1000;

                // Crystal and Splint gloves have NO direct HP - only endurance
                if (isCrystal || isSplint)
                {
                    hp = 0;
                }
                else
                {

                    //GLOVES PLATE AND CHAINcompletely tested 46-100in dungeons///////
                    if (playerLevel == 48) hp += 1;
                    if (playerLevel == 49) hp += 1;
                    if (playerLevel >= 53) hp -= 1;
                    if (playerLevel >= 54) hp += 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 65) hp -= 1;
                    if (playerLevel >= 71) hp += 1;
                    if (playerLevel >= 72) hp -= 2;
                    if (playerLevel >= 74) hp += 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 85) hp -= 1;
                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 93) hp += 1;
                    if (playerLevel >= 94) hp -= 1;
                    if (playerLevel >= 96) hp += 1;
                    if (playerLevel >= 96) hp -= 1;
                }

                int end = 0;
                if (!hasAgilityNotEndurance)
                {
                    int endOffset = 2;
                    if (playerLevel >= 60) endOffset = 3;
                    int primPool = 20 + (itemLevel + endOffset) * 1090 / 109;

                    // Crystal and Splint gloves use same formula (0.8 End)
                    if (isCrystal || isSplint)
                    {
                        int crystalEndOffset = 1;
                        int crystalPrimPool = 20 + (itemLevel + crystalEndOffset) * 1090 / 109;
                        end = crystalPrimPool / 24;
                        if (playerLevel == 42 || playerLevel == 47 || playerLevel == 52 || playerLevel == 54 || playerLevel == 59 ||
        playerLevel == 64 || playerLevel == 66 || playerLevel == 69 || playerLevel == 71 || playerLevel == 74 ||
        playerLevel == 76 || playerLevel == 78 || playerLevel == 79 || playerLevel == 81 || playerLevel == 83 ||
        playerLevel == 86 || playerLevel == 88 || playerLevel == 90 || playerLevel == 91 || playerLevel == 93 ||
        playerLevel == 95 || playerLevel == 96 || playerLevel == 98 || playerLevel == 100) end -= 1;
                    }
                    else
                    {
                        end = primPool / 20 / 2;
                    }
                }
                int mod = hasMaxHitPointB ? hp * 256 : 0;
                return (hp, end, mod);
            }


            //BOOTS - Crystal has 0.8 End NO HP, Splint has 1.0 End + HP
            if (gcLower.Contains("boot") || gcLower.Contains("greave"))
            {
                int slotPool = maxPool / 10;
                int hp = slotPool * 537 / 1000;

                // Crystal boots have NO direct HP
                if (isCrystal)
                {
                    hp = 0;
                }
                // Splint boots HAVE HP - use Crystal helm-style HP formula
                else if (isSplint)
                {
                    int splintItemLevel = playerLevel + 3;
                    hp = splintItemLevel * 719 / 97 - 14;  // May need adjustment after testing
                }
                else
                {
                    if (playerLevel > 50)
                    {
                        hp -= (playerLevel - 50) / 5;
                    }
                    //BOOTS pLATE AND cHAIN completely tested 46-100in dungeons///////
                    if (playerLevel == 46) hp += 1;
                    if (playerLevel == 47) hp += 1;
                    if (playerLevel == 49) hp += 1;
                    if (playerLevel >= 53) hp -= 1;
                    if (playerLevel >= 54) hp += 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 60) hp += 1;
                    if (playerLevel >= 63) hp -= 1;
                    if (playerLevel >= 63) hp += 1;
                    if (playerLevel >= 68) hp -= 1;
                    if (playerLevel >= 70) hp += 1;
                    if (playerLevel >= 72) hp -= 1;
                    if (playerLevel >= 75) hp += 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 80) hp += 1;
                    if (playerLevel >= 82) hp -= 1;
                    if (playerLevel >= 86) hp += 1;
                    if (playerLevel >= 87) hp -= 1;
                    if (playerLevel >= 91) hp += 1;
                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 100) hp += 1;
                }

                int endOffset = 1;
                if (playerLevel == 49) endOffset = 2;
                if (playerLevel >= 53) endOffset = 2;
                if (playerLevel >= 60) endOffset = 3;
                int primPool = 20 + (itemLevel + endOffset) * 1090 / 109;

                int end;
                // Crystal boots use 0.8 End formula
                if (isCrystal)
                {
                    if (playerLevel <= 57)
                    {
                        end = itemLevel / 2 + 2;
                    }
                    else
                    {
                        end = (itemLevel + 5) / 2;
                    }
                }
                // Splint boots use 1.0 End - higher than Crystal
                else if (isSplint)
                {
                    if (playerLevel <= 57)
                    {
                        end = itemLevel / 2 + 4;  // +2 more than Crystal for 1.0 vs 0.8
                    }
                    else
                    {
                        end = (itemLevel + 9) / 2;  // May need adjustment after testing
                    }
                }
                else
                {
                    end = primPool / 20 / 2;
                }

                int mod = hasMaxHitPointB ? hp * 256 : 0;
                return (hp, end, mod);
            }

            //HELMS - Crystal has 0.8 End + HP, Splint has 1.0 End + HP
            if (gcLower.Contains("helm"))
            {
                int slotPool = maxPool / 10;
                int hp = slotPool * 537 / 1000;
                // Crystal Helm uses different HP formula
                if (isCrystal)
                {
                    int crystalItemLevel = playerLevel + 7;
                    hp = crystalItemLevel * 719 / 97 - 10;
                    if (playerLevel == 66) hp -= 1;
                    if (playerLevel == 78) hp -= 1;
                    if (playerLevel == 83) hp -= 1;
                    if (playerLevel == 88) hp -= 1;
                    if (playerLevel == 90) hp -= 1;
                    if (playerLevel == 95) hp -= 1;
                    if (playerLevel == 100) hp -= 1;
                }
                // Splint Helm also has HP - try same formula as Crystal
                else if (isSplint)
                {
                    int splintItemLevel = playerLevel + 7;
                    hp = splintItemLevel * 719 / 97 - 10;  // Same as Crystal, may need adjustment
                    if (playerLevel == 66) hp -= 1;
                    if (playerLevel == 78) hp -= 1;
                    if (playerLevel == 83) hp -= 1;
                    if (playerLevel == 88) hp -= 1;
                    if (playerLevel == 90) hp -= 1;
                    if (playerLevel == 95) hp -= 1;
                    if (playerLevel == 100) hp -= 1;
                }
                else
                {
                    if (playerLevel > 50)
                    {
                        hp -= (playerLevel - 50) / 5;
                    }
                    // HELMS Plate and Chain completely tested 46 - 100in dungeons  need to test lower levels ///////
                    if (playerLevel == 46) hp += 1;
                    if (playerLevel == 47) hp += 1;
                    if (playerLevel == 49) hp += 1;
                    if (playerLevel >= 53) hp -= 1;
                    if (playerLevel >= 54) hp += 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 60) hp += 1;
                    if (playerLevel >= 63) hp -= 1;
                    if (playerLevel >= 64) hp += 1;
                    if (playerLevel >= 68) hp -= 1;
                    if (playerLevel >= 70) hp += 1;
                    if (playerLevel >= 72) hp -= 1;
                    if (playerLevel >= 75) hp += 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 80) hp += 1;
                    if (playerLevel >= 82) hp -= 1;
                    if (playerLevel >= 86) hp += 1;
                    if (playerLevel >= 82) hp -= 1;
                    if (playerLevel >= 91) hp += 1;
                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 100) hp += 1;
                }

                int end = 0;
                int primPool = 0;
                if (!hasAgilityNotEndurance)
                {
                    int endOffset = 2;
                    if (playerLevel >= 58) endOffset = 3;
                    primPool = 20 + (itemLevel + endOffset) * 1090 / 109;

                    // Crystal Helm uses 0.8 End formula
                    if (isCrystal)
                    {
                        int crystalPrimPool = 20 + (itemLevel - 1) * 1090 / 109;
                        end = crystalPrimPool * 8 / 100 + 3;
                        if (playerLevel == 57) end += 1;
                        if (playerLevel == 62) end += 1;
                        if (playerLevel == 67) end += 1;
                        if (playerLevel == 72) end += 1;
                        if (playerLevel == 73) end += 1;
                        if (playerLevel == 77) end += 1;
                        if (playerLevel == 78) end += 1;
                        if (playerLevel == 82) end += 1;
                        if (playerLevel == 83) end += 1;
                        if (playerLevel == 84) end += 1;
                        if (playerLevel == 87) end += 1;
                        if (playerLevel == 88) end += 1;
                        if (playerLevel == 89) end += 1;
                        if (playerLevel == 92) end += 1;
                        if (playerLevel == 93) end += 1;
                        if (playerLevel == 94) end += 1;
                        if (playerLevel == 97) end += 1;
                        if (playerLevel == 98) end += 1;
                        if (playerLevel == 99) end += 1;
                        if (playerLevel == 100) end += 1;
                    }
                    // Splint Helm uses 1.0 End - scale up by 1.0/0.8 = 1.25
                    else if (isSplint)
                    {
                        int splintPrimPool = 20 + (itemLevel - 1) * 1090 / 109;
                        end = splintPrimPool * 10 / 100 + 3;  // 10/100 instead of 8/100 for 1.0 vs 0.8
                                                              // May need level adjustments after testing
                    }
                    else
                    {
                        end = primPool / 10 / 2;
                    }
                }

                int mod = hasMaxHitPointB ? hp * 256 : 0;
                return (hp, end, mod);
            }

            //Armor - Crystal has 0.8 End NO HP, Splint has 0.8 End + HP
            if (gcLower.Contains("armor") || gcLower.Contains("chest") || gcLower.Contains("body"))
            {
                int slotPool = maxPool * 15 / 100;
                int hp = slotPool * 537 / 1000;
                // Crystal armor has NO direct HP - only endurance
                if (isCrystal)
                {
                    hp = 0;
                }
                // Splint armor HAS HP - uses ~2x multiplier
                else if (isSplint)
                {
                    hp = slotPool * 1045 / 1000 + (103 - playerLevel) / 3;
                    // Small fixes for levels off by 1
                    if (playerLevel == 38 || playerLevel == 39 || playerLevel == 43 || playerLevel == 49 || playerLevel == 51 || playerLevel == 52 || playerLevel == 70) hp -= 1;
                    if (playerLevel == 44 || playerLevel == 80 || playerLevel == 92) hp += 1;
                }
                else
                {
                    //Armor   PLATE AND CHAIN completely tested 46-100in dungeons///////
                    if (playerLevel == 46) hp += 2;
                    if (playerLevel == 47) hp += 1;
                    if (playerLevel == 48) hp += 1;
                    if (playerLevel >= 51 && playerLevel < 55) hp -= 1;
                    if (playerLevel >= 55) hp -= 1;
                    if (playerLevel >= 56) hp -= 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 59) hp += 1;
                    if (playerLevel >= 60) hp -= 1;
                    if (playerLevel >= 63) hp -= 1;
                    if (playerLevel >= 65) hp -= 1;
                    if (playerLevel >= 67) hp -= 1;
                    if (playerLevel >= 69) hp -= 1;
                    if (playerLevel >= 70) hp += 1;
                    if (playerLevel >= 72) hp -= 1;
                    if (playerLevel >= 74) hp -= 1;
                    if (playerLevel >= 75) hp += 1;
                    if (playerLevel >= 76) hp -= 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 81) hp -= 1;
                    if (playerLevel >= 83) hp -= 1;
                    if (playerLevel >= 87) hp -= 1;
                    if (playerLevel >= 90) hp -= 1;
                    if (playerLevel >= 90) hp += 1;
                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 94) hp -= 1;
                    if (playerLevel >= 96) hp -= 1;
                    if (playerLevel >= 99) hp -= 1;
                }
                int endOffset = Math.Min(2 + (playerLevel - 50) / 7, 3);
                int primPool = 20 + (itemLevel + endOffset) * 1090 / 109;
                int end;
                // Crystal and Splint armor both use 0.8 End - same formula
                if (isCrystal || isSplint)
                {
                    int crystalEndOffset = Math.Min(endOffset + 2, 3);
                    int crystalPrimPool = 20 + (itemLevel + crystalEndOffset) * 1090 / 109;
                    end = crystalPrimPool * 4 / 25;
                    if (playerLevel == 39 || playerLevel == 42 || playerLevel == 44 || playerLevel == 47 || playerLevel == 52) end -= 1;
                    if (playerLevel == 65 || playerLevel == 70 || playerLevel == 73 || playerLevel == 75 || playerLevel == 76 ||
                        playerLevel == 78 || (playerLevel >= 80 && playerLevel != 82 && playerLevel != 87)) end += 1;
                    if (playerLevel == 100) end += 1;
                }
                else
                {
                    end = primPool / 5 / 2;
                }
                int mod = hasMaxHitPointB ? hp * 256 : 0;
                return (hp, end, mod);
            }

            //SHOULDERS - Crystal and Splint both have 0.8 End, NO HP
            if (gcLower.Contains("shoulder") || gcLower.Contains("pauldron"))
            {
                int shoulderItemLevel = playerLevel + 3;
                int shoulderMaxPool = 50 + (shoulderItemLevel - 1) * 7950 / 109;
                int slotPool = shoulderMaxPool / 20;
                int hp = slotPool * 537 / 1000;

                // Crystal and Splint shoulders have NO direct HP - only endurance
                if (isCrystal || isSplint)
                {
                    hp = 0;
                }
                else
                {

                    //SHOULDERS PLATE AND CHAIN completely tested 46-100in dungeons///////
                    if (playerLevel == 48) hp += 1;
                    if (playerLevel == 49) hp += 1;
                    if (playerLevel >= 53) hp -= 1;
                    if (playerLevel >= 54) hp += 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 65) hp -= 1;
                    if (playerLevel >= 71) hp += 1;
                    if (playerLevel >= 72) hp -= 2;
                    if (playerLevel >= 74) hp += 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 85) hp -= 1;
                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 93) hp += 1;
                    if (playerLevel >= 94) hp -= 1;
                    if (playerLevel >= 96) hp += 1;
                    if (playerLevel >= 98) hp -= 1;
                }

                int end = 0;
                if (!hasAgilityNotEndurance)
                {
                    int endOffset = Math.Min(2 + (playerLevel - 50) / 8, 3);
                    int primPool = 20 + (shoulderItemLevel + endOffset) * 1090 / 109;

                    // Crystal and Splint shoulders use same formula (0.8 End)
                    if (isCrystal || isSplint)
                    {
                        if (playerLevel <= 57)
                        {
                            int crystalEndOffset = 1;
                            int crystalPrimPool = 20 + (shoulderItemLevel + crystalEndOffset) * 1090 / 109;
                            end = (crystalPrimPool - 1) / 12;
                            if (playerLevel == 47 || playerLevel == 52 || playerLevel == 53) end -= 1;
                        }
                        else
                        {
                            end = shoulderItemLevel - 9;
                            if (playerLevel >= 63) end -= 1;
                            if (playerLevel >= 68) end -= 1;
                            if (playerLevel >= 74) end -= 1;
                            if (playerLevel >= 79) end -= 1;
                            if (playerLevel >= 85) end -= 1;
                            if (playerLevel >= 90) end -= 1;
                            if (playerLevel >= 95) end -= 1;

                        }
                    }
                    else
                    {
                        end = primPool / 10 / 2;
                    }
                }
                int mod = hasMaxHitPointB ? hp * 256 : 0;
                return (hp, end, mod);
            }


            //SHIELD - Crystal has 0.8 End NO HP, Splint has 1.0 End NO HP
            if (gcLower.Contains("shield"))
            {
                int slotPool = maxPool / 10;
                int hp = slotPool * 537 / 1000;
                //SHIELDS SPOT tested 38-100in dungeons///////
                // Crystal, Chain and Splint shields have no direct HP bonus
                if (isChain || isCrystal || isSplint) hp = 0;

                if (!isCrystal && !isChain && !isSplint)
                {
                    if (playerLevel > 50)
                    {
                        hp -= (playerLevel - 50) / 5;
                    }
                    //SHIELDS pLATE AND CHAIN completely tested 46-100in dungeons///////
                    if (playerLevel == 49) hp += 1;
                    if (playerLevel >= 53) hp -= 1;
                    if (playerLevel >= 54) hp += 1;
                    if (playerLevel >= 58) hp -= 1;
                    if (playerLevel >= 60) hp += 1;
                    if (playerLevel >= 63) hp -= 2;
                    if (playerLevel >= 64) hp += 2;
                    if (playerLevel >= 68) hp -= 1;
                    if (playerLevel >= 70) hp += 1;
                    if (playerLevel >= 72) hp -= 1;
                    if (playerLevel >= 75) hp += 1;
                    if (playerLevel >= 78) hp -= 1;
                    if (playerLevel >= 80) hp += 1;
                    if (playerLevel >= 82) hp += 1;
                    if (playerLevel >= 86) hp += 1;
                    if (playerLevel >= 87) hp -= 3;
                    if (playerLevel >= 90) hp -= 1;
                    if (playerLevel >= 91) hp += 2;
                    if (playerLevel >= 92) hp -= 1;
                    if (playerLevel >= 96) hp += 1;
                    if (playerLevel >= 98) hp -= 1;
                    if (playerLevel >= 100) hp += 1;
                }

                int endOffset = 2;
                if (playerLevel >= 58) endOffset = 3;
                int primPool = 20 + (itemLevel + endOffset) * 1090 / 109;

                int end;
                // Crystal shield uses 0.8 End (armor-style)
                if (isCrystal)
                {
                    end = primPool / 5 / 2;
                }
                // Splint shield uses 1.0 End - higher than Crystal
                else if (isSplint)
                {
                    end = primPool / 4 / 2;  // 1/4 instead of 1/5 for 1.0 vs 0.8
                }
                else
                {
                    end = primPool / 10 / 2;
                }

                return (hp, end, 0);
            }

            return (0, 0, 0);
        }

        public void CalculateEquipmentBonuses(string connId, GCObject avatar)
        {
            PlayerState playerState = GetPlayerState(connId);
            playerState.ClearEquipmentBonuses();

            // Reset weapon to defaults — will be overwritten if weapon found
            float bestWeaponDamage = 1.0f;
            float bestWeaponVolatility = 0.5f;
            int bestWeaponLevel = 1;
            string bestWeaponClass = "1HMELEE";
            int bestWeaponRange = 8;
            float bestWeaponCooldown = 1.75f;
            bool foundWeapon = false;

            if (avatar == null) { Debug.LogError("[EQUIP-STATS] avatar is NULL"); return; }
            var equipment = avatar.Children?.FirstOrDefault(c => c.GCClass == "avatar.base.Equipment");

            // Build item list: tracked items are AUTHORITATIVE after spawn.
            // Avatar children are stale (never updated on equip/unequip).
            var allItems = new Dictionary<string, GCObject>(StringComparer.OrdinalIgnoreCase);
            if (_playerEquippedItems.ContainsKey(connId))
            {
                // Use tracked items exclusively — updated by equip/unequip handlers
                var tracked = _playerEquippedItems[connId];
                foreach (var kvp in tracked)
                    if (kvp.Value?.GCClass != null)
                        allItems[kvp.Value.GCClass] = kvp.Value;
                Debug.LogError($"[EQUIP-STATS] Using {tracked.Count} TRACKED items (authoritative)");
            }
            else if (equipment?.Children != null)
            {
                // Fallback: first spawn before any tracking exists
                foreach (var child in equipment.Children)
                    allItems[child.GCClass ?? ""] = child;
                Debug.LogError($"[EQUIP-STATS] Using {allItems.Count} AVATAR children (fallback, no tracking yet)");
            }

            Debug.LogError($"[EQUIP-STATS] Processing {allItems.Count} equipped items, DB loaded={DungeonRunners.Data.ItemStatDatabase.Instance.IsLoaded}");

            var itemStatDb = DungeonRunners.Data.ItemStatDatabase.Instance;

            foreach (var item in allItems.Values)
            {
                string gc = item.GCClass ?? "";
                int rarity = item.GetEffectiveRarity();
                string pattern = DungeonRunners.Data.ItemStatDatabase.ExtractPattern(gc);
                bool isWeapon = item.NativeClass == "MeleeWeapon" || item.NativeClass == "RangedWeapon";

                // WEAPONS: Use per-item DB (exact mods per weapon, /8 slot divisor)
                // Old code returned (0,0,0) for all weapons — DB fixes that
                if (isWeapon && itemStatDb.IsLoaded && itemStatDb.HasItem(gc))
                {
                    var stats = itemStatDb.GetItemStats(gc, playerState.Level, 8);
                    var attrs = itemStatDb.GetItemAttributes(gc);
                    Debug.LogError($"[EQUIP-ITEM] {gc} → DB hit! {stats.Count} stats: {string.Join(", ", attrs)}");

                    stats.TryGetValue("MAX_HIT_POINTS", out int hpBonus);
                    stats.TryGetValue("ENDURANCE", out int endBonus);
                    stats.TryGetValue("MAX_MANA_POINTS", out int manaBonus);
                    stats.TryGetValue("INTELLECT", out int intBonus);

                    if (hpBonus > 0) playerState.AddTotalHealthBonus(hpBonus);
                    if (endBonus > 0) playerState.AddEnduranceBonus(endBonus);
                    if (manaBonus > 0) playerState.AddManaBonus(manaBonus);
                    if (intBonus > 0) playerState.AddIntellectManaBonus(intBonus);

                    // Accumulate ALL stats for character tracking
                    foreach (var kvp in stats)
                    {
                        if (playerState.EquipmentStats.ContainsKey(kvp.Key))
                            playerState.EquipmentStats[kvp.Key] += kvp.Value;
                        else
                            playerState.EquipmentStats[kvp.Key] = kvp.Value;
                    }

                    if (hpBonus > 0 || endBonus > 0 || manaBonus > 0 || intBonus > 0)
                        Debug.LogError($"[EQUIP-STATS] {gc}: HP+{hpBonus} END+{endBonus} MANA+{manaBonus} INT+{intBonus}(+{intBonus * 17}mp)");
                }
                else
                {
                    // ARMOR + non-DB items: Use tested hardcoded formulas
                    bool isMythic = gc.IndexOf("Mythic", StringComparison.OrdinalIgnoreCase) >= 0;
                    bool isPlate = gc.ToLower().Contains("plate");
                    var (hp, endurance, modHP) = CalculateItemBonuses(gc, playerState.Level, isMythic);
                    if (hp > 0) playerState.AddTotalHealthBonus(hp);
                    if (endurance > 0) playerState.AddEnduranceBonus(endurance);
                    if (modHP > 0 && isPlate) playerState.AddModifierHPBonus((uint)modHP);

                    // Track HP/END from armor in EquipmentStats too
                    if (hp > 0)
                    {
                        if (playerState.EquipmentStats.ContainsKey("MAX_HIT_POINTS"))
                            playerState.EquipmentStats["MAX_HIT_POINTS"] += hp;
                        else
                            playerState.EquipmentStats["MAX_HIT_POINTS"] = hp;
                    }
                    if (endurance > 0)
                    {
                        if (playerState.EquipmentStats.ContainsKey("ENDURANCE"))
                            playerState.EquipmentStats["ENDURANCE"] += endurance;
                        else
                            playerState.EquipmentStats["ENDURANCE"] = endurance;
                    }

                    Debug.LogError($"[EQUIP-ITEM] {gc} → pattern={pattern} rarity={rarity} (fallback) HP+{hp} END+{endurance}");
                }

                // Check if this is a weapon — update WeaponDamage for combat formula
                if (item.NativeClass == "MeleeWeapon" || item.NativeClass == "RangedWeapon")
                {
                    var weaponData = DatabaseLoader.FindItem(gc);
                    if (weaponData != null && weaponData.damage > 0)
                    {
                        var weaponStats = GCDatabase.Instance.GetWeaponStats(gc);
                        bestWeaponDamage = weaponData.damage;
                        bestWeaponVolatility = Mathf.Clamp(weaponStats.volatility, 0f, 0.95f);
                        bestWeaponLevel = Math.Max(1, item.StoredLevel >= 0 ? item.StoredLevel : DungeonRunners.Managers.RarityHelper.GetItemLevel(gc));
                        bestWeaponClass = weaponData.weaponClass ?? "1HMELEE";
                        bestWeaponRange = weaponData.range > 0 ? weaponData.range : 8;
                        bestWeaponCooldown = weaponData.cooldown > 0 ? weaponData.cooldown : 1.75f;
                        foundWeapon = true;
                        Debug.LogError($"[EQUIP-WEAPON] {gc}: dmg={bestWeaponDamage:F2} vol={bestWeaponVolatility:F2} level={bestWeaponLevel} class={bestWeaponClass} range={bestWeaponRange} cd={bestWeaponCooldown:F2}");
                    }
                }
            }
            RecalculateHotbarPassiveBonuses(connId);
            playerState.RecalculateCurrentHP();

            // Mana: always set to new max after equipment change (client fills mana on equip/unequip)
            playerState.SetCurrentMana(playerState.MaxManaWire);

            // Log total equipment stats
            Debug.LogError($"[EQUIP-TOTAL] MaxHP={playerState.MaxHPWire / 256} MaxMana={playerState.MaxManaWire / 256} EquipStats={playerState.EquipmentStats.Count}");
            foreach (var kvp in playerState.EquipmentStats)
                Debug.LogError($"[EQUIP-TOTAL]   {kvp.Key} = {kvp.Value}");

            // Update weapon stats on PlayerState
            if (foundWeapon)
            {
                playerState.WeaponDamage = bestWeaponDamage;
                playerState.WeaponDamageVolatility = bestWeaponVolatility;
                playerState.WeaponLevel = bestWeaponLevel;
                playerState.WeaponClass = bestWeaponClass;
                playerState.WeaponRange = bestWeaponRange;
                playerState.WeaponCooldown = bestWeaponCooldown;
                Debug.LogError($"[EQUIP-WEAPON] PlayerState updated: dmg={bestWeaponDamage:F2} vol={bestWeaponVolatility:F2} level={bestWeaponLevel} class={bestWeaponClass}");
            }
        }
