        private (int hp, int end, int mod) GetItemHPBonusesWithModifier(string gcClass, bool isPlate)
        {
            string gcLower = gcClass.ToLower();
            int plateModHP = isPlate ? 376 : 0;

            if (gcLower.Contains("helm1"))
                return (213, 29, plateModHP);
            if (gcLower.Contains("armor1"))
                return (0, 59, 0);
            if (gcLower.Contains("boots1"))
                return (0, 14, 0);
            if (gcLower.Contains("gloves1"))
                return (0, 14, 0);

            return (0, 0, 0);
        }
