        /// <summary>Goto objective metadata from Q*.gc files.</summary>
        private struct GotoGCData
        {
            public readonly string TargetZone;
            public readonly string TargetEntity;
            public readonly int Range;
            public GotoGCData(string zone, string entity, int range)
            { TargetZone = zone; TargetEntity = entity; Range = range; }
        }

        /// <summary>
        /// Gives the onAcceptItem to the player when they accept a quest.
        /// Places directly into inventory using submsg 0x1E — same as merchant quest item buy.
        /// </summary>
        private void GiveOnAcceptItem(RRConnection conn, string onAcceptItem)
        {
            if (string.IsNullOrEmpty(onAcceptItem)) return;

            // Map onAcceptItem ItemGenerator names to actual GC item types.
            // Source of truth: <Generator>.gc files in /Database/gc/
            //   NormalScrollIG  -> items.consumables.Consumable_TownPortal (1-use town portal)
            //   (Previously hardcoded to scrollpal.permawaypointscroll = the COMPASS,
            //    which is the member-only Permanent Waypoint Scroll. Wrong item.)
            string gcClass = onAcceptItem;
            if (onAcceptItem.Equals("NormalScrollIG", StringComparison.OrdinalIgnoreCase))
                gcClass = "items.consumables.Consumable_TownPortal";

            Debug.LogError($"[QUEST-ACCEPT-ITEM] Giving item: {onAcceptItem} → GCClass={gcClass}");

            string connId = conn.ConnId.ToString();
            var playerState = GetPlayerState(connId);
            if (playerState == null || conn.UnitContainerId == 0) return;

            // Look up item dimensions
            var itemData = DatabaseLoader.FindItem(gcClass);
            int itemWidth = itemData?.inventoryWidth ?? 1;
            int itemHeight = itemData?.inventoryHeight ?? 1;

            // Find empty inventory slot
            byte slotX = 0, slotY = 0;
            bool foundSlot = false;
            for (byte row = 0; row < 8 && !foundSlot; row++)
                for (byte col = 0; col < 10 && !foundSlot; col++)
                    if (!IsInventorySlotOccupied(connId, col, row, itemWidth, itemHeight))
                    { slotX = col; slotY = row; foundSlot = true; }

            if (!foundSlot)
            {
                Debug.LogError($"[QUEST-ACCEPT-ITEM] Inventory full! Cannot give {gcClass}");
                return;
            }

            uint slot = GetNextInventorySlot(connId);

            // Send item directly to inventory via UnitContainer 0x1E
            // Same format as MerchantManager quest item buy
            var writer = new LEWriter();
            writer.WriteByte(0x07);  // BeginStream

            writer.WriteByte(0x35);
            writer.WriteUInt16(conn.UnitContainerId);
            writer.WriteByte(0x1E);          // Add item to inventory
            writer.WriteByte(0x0B);          // inventory container ID
            writer.WriteByte(0xFF);          // marker
            writer.WriteCString(GCObject.GetPacketGCClassFor(gcClass));    // GC type
            writer.WriteUInt32(slot);        // slot index
            writer.WriteByte(slotX);         // grid X
            writer.WriteByte(slotY);         // grid Y
            writer.WriteByte(0x01);          // quantity
            writer.WriteByte(0x01);          // level
            writer.WriteByte(0x00);          // flags
            writer.WriteByte(0x00);          // modifier count
            WritePlayerEntitySynch(conn, writer);

            writer.WriteByte(0x06);  // EndStream

            byte[] packet = writer.ToArray();
            Debug.LogError($"[QUEST-ACCEPT-ITEM] Sending 0x1E packet ({packet.Length} bytes): {BitConverter.ToString(packet)}");
            SendCompressedA(conn, 0x01, 0x0F, packet);

            // Track in server inventory
            var newItem = new GCObject { GCClass = gcClass, NativeClass = "Item" };
            TrackInventoryItem(connId, slot, newItem, slotX, slotY);
            OccupyInventorySlots(connId, slotX, slotY, itemWidth, itemHeight);
            SetStackCount(connId, slot, 1);

            // Save to DB
            SavePlayerInventory(conn);

            Debug.LogError($"[QUEST-ACCEPT-ITEM] ✅ {gcClass} placed in inventory at ({slotX},{slotY}) slot {slot}");
        }

        /// <summary>
        /// Give the player N stackable items of a given gcType. Tops up existing stacks
        /// first via 0x22 UpdateQuantity, then creates new 1×1 stacks for the remainder
        /// via 0x1E AddItem. Used for King's Coin rewards (QuestItemPAL.Token, max stack 100)
        /// and any other stackable item.
        ///
        /// Per RE of DungeonRunners.exe: King's Coins are NOT a separate currency. The
        /// Container only has one currency (gold at +0x74). King's Coins are inventory
        /// items of type QuestItemPAL.Token and the bottom-left inventory counter is
        /// computed client-side via Inventory::getItemCountByType("QuestItemPAL.Token").
        /// To make the counter increment, just add Token items via 0x1E (same path as
        /// GiveOnAcceptItem).
        /// </summary>
        private void GiveStackedItem(RRConnection conn, string gcType, int totalCount, int maxStackSize = 100)
        {
            if (totalCount <= 0 || string.IsNullOrEmpty(gcType)) return;
            if (conn.UnitContainerId == 0)
            {
                Debug.LogError($"[GIVE-STACKED] No UnitContainerId — cannot give {gcType}");
                return;
            }

            string connId = conn.ConnId.ToString();
            int remaining = totalCount;

            Debug.LogError($"[GIVE-STACKED] {gcType} ×{totalCount} (max stack {maxStackSize})");

            // ── Step 1: Top up existing stacks via 0x22 UpdateQuantity ──
            if (_playerInventoryItems.ContainsKey(connId))
            {
                var slots = new List<uint>(_playerInventoryItems[connId].Keys);
                foreach (var slotId in slots)
                {
                    if (remaining <= 0) break;
                    var entry = _playerInventoryItems[connId][slotId];
                    if (entry.item == null) continue;
                    if (!string.Equals(entry.item.GCClass, gcType, StringComparison.OrdinalIgnoreCase))
                        continue;

                    int currentCount = GetStackCount(connId, slotId);
                    if (currentCount >= maxStackSize) continue;

                    int canAdd = System.Math.Min(maxStackSize - currentCount, remaining);
                    int newCount = currentCount + canAdd;
                    remaining -= canAdd;

                    // 0x22 processUpdateQuantity (0x57dc50 in client):
                    //   reads uint32 itemSlotId + byte newQuantity
                    //   stores newQuantity at item+0x82 (the cached stack count byte)
                    var qWriter = new LEWriter();
                    qWriter.WriteByte(0x07);
                    qWriter.WriteByte(0x35);
                    qWriter.WriteUInt16(conn.UnitContainerId);
                    qWriter.WriteByte(0x22);
                    qWriter.WriteUInt32(slotId);
                    qWriter.WriteByte((byte)(newCount > 255 ? 255 : newCount));
                    WritePlayerEntitySynch(conn, qWriter);
                    qWriter.WriteByte(0x06);
                    SendCompressedA(conn, 0x01, 0x0F, qWriter.ToArray());

                    SetStackCount(connId, slotId, newCount);
                    Debug.LogError($"[GIVE-STACKED] Topped up slot {slotId} {currentCount}→{newCount} (+{canAdd})");
                }
            }

            // ── Step 2: Create new 1×1 stacks for the remainder via 0x1E AddItem ──
            var itemData = DatabaseLoader.FindItem(gcType);
            int itemWidth = itemData?.inventoryWidth ?? 1;
            int itemHeight = itemData?.inventoryHeight ?? 1;

            while (remaining > 0)
            {
                var (sx, sy) = FindNextFreeInventorySlot(connId, itemWidth, itemHeight);
                if (sx < 0)
                {
                    Debug.LogError($"[GIVE-STACKED] ⚠️ Inventory full! {remaining}× {gcType} not given");
                    break;
                }
                byte slotX = (byte)sx, slotY = (byte)sy;

                int stackSize = System.Math.Min(remaining, maxStackSize);
                remaining -= stackSize;
                uint slot = GetNextInventorySlot(connId);

                var writer = new LEWriter();
                writer.WriteByte(0x07);
                writer.WriteByte(0x35);
                writer.WriteUInt16(conn.UnitContainerId);
                writer.WriteByte(0x1E);
                writer.WriteByte(0x0B);
                writer.WriteByte(0xFF);
                writer.WriteCString(GCObject.GetPacketGCClassFor(gcType));
                writer.WriteUInt32(slot);
                writer.WriteByte(slotX);
                writer.WriteByte(slotY);
                writer.WriteByte((byte)(stackSize > 255 ? 255 : stackSize));
                writer.WriteByte(0x01);
                writer.WriteByte(0x00);
                writer.WriteByte(0x00);
                WritePlayerEntitySynch(conn, writer);
                writer.WriteByte(0x06);
                SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());

                var newItem = new GCObject { GCClass = gcType, NativeClass = "Item" };
                TrackInventoryItem(connId, slot, newItem, slotX, slotY);
                OccupyInventorySlots(connId, slotX, slotY, itemWidth, itemHeight);
                SetStackCount(connId, slot, stackSize);

                Debug.LogError($"[GIVE-STACKED] New stack: slot {slot} at ({slotX},{slotY}) ×{stackSize}");
            }

            SavePlayerInventory(conn);
            Debug.LogError($"[GIVE-STACKED] ✅ Done. {totalCount - remaining}/{totalCount} {gcType} placed");
        }

        /// <summary>
        /// Swap minor potion drops to their major equivalents for member players.
        /// Original DR enforced stack-of-10 by giving members DIFFERENT ITEMS (Major
        /// potions have MaxStackSize=10 in their GC data, minors have MaxStackSize=5).
        /// The client enforces those caps - we cannot make a minor potion stack to 10.
        ///
        /// Logs EVERY drop's gcType + final value so we can see exactly what is in
        /// the items DB and what got swapped. If members are still seeing stack-of-5
        /// after this, the log will tell us why (helper not called / helper called but
        /// no potions in drops / potion gcType doesn't match the patterns).
        /// </summary>
        private void UpgradePotionsForMembers(List<LootDrop> drops, RRConnection conn)
        {
            string who = conn?.LoginName ?? "<null>";
            if (drops == null) { Debug.LogError($"[LOOT-MEMBER] {who}: drops==null, skipping"); return; }
            if (conn == null) { Debug.LogError($"[LOOT-MEMBER] <null conn>: drops.Count={drops.Count}, skipping"); return; }

            bool isFree = IsPlayerFree(conn.LoginName);
            bool isAdmin = IsPlayerAdmin(conn.LoginName);
            Debug.LogError($"[LOOT-MEMBER] called for {who} isFree={isFree} isAdmin={isAdmin} drops.Count={drops.Count}");

            foreach (var drop in drops)
            {
                if (drop == null) { Debug.LogError("[LOOT-MEMBER]   drop=null"); continue; }
                if (drop.IsGold) { Debug.LogError($"[LOOT-MEMBER]   gold +{drop.GoldAmount}"); continue; }
                Debug.LogError($"[LOOT-MEMBER]   item gcType='{drop.GCType ?? "<null>"}' label='{drop.Label ?? "<null>"}'");
            }

            if (isFree) { Debug.LogError($"[LOOT-MEMBER] {who} is free, no upgrades"); return; }

            int swapped = 0;
            foreach (var drop in drops)
            {
                if (drop == null || drop.IsGold || string.IsNullOrEmpty(drop.GCType)) continue;
                string gc = drop.GCType;
                string lc = gc.ToLowerInvariant();
                string before = gc;

                // Pattern A: literal "Minor*Potion" anywhere (case-insensitive)
                if (lc.Contains("minorhealthpotion"))
                {
                    drop.GCType = System.Text.RegularExpressions.Regex.Replace(
                        gc, "minorhealthpotion", "MajorHealthPotion",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                    drop.Label = "Major Health Potion";
                    Debug.LogError($"[LOOT-MEMBER]   SWAP A-H: '{before}' -> '{drop.GCType}'");
                    swapped++;
                    continue;
                }
                if (lc.Contains("minormanapotion"))
                {
                    drop.GCType = System.Text.RegularExpressions.Regex.Replace(
                        gc, "minormanapotion", "MajorManaPotion",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                    drop.Label = "Major Mana Potion";
                    Debug.LogError($"[LOOT-MEMBER]   SWAP A-M: '{before}' -> '{drop.GCType}'");
                    swapped++;
                    continue;
                }

                // Pattern B: PotionPAL alternate naming "HealthPotion_Sm" / "ManaPotion_Sm"
                // (seen in FreePotionIG.gc comments) -> "_Lg" suffix
                if (lc.Contains("healthpotion_sm"))
                {
                    drop.GCType = System.Text.RegularExpressions.Regex.Replace(
                        gc, "healthpotion_sm", "HealthPotion_Lg",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                    drop.Label = "Major Health Potion";
                    Debug.LogError($"[LOOT-MEMBER]   SWAP B-H: '{before}' -> '{drop.GCType}'");
                    swapped++;
                    continue;
                }
                if (lc.Contains("manapotion_sm"))
                {
                    drop.GCType = System.Text.RegularExpressions.Regex.Replace(
                        gc, "manapotion_sm", "ManaPotion_Lg",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                    drop.Label = "Major Mana Potion";
                    Debug.LogError($"[LOOT-MEMBER]   SWAP B-M: '{before}' -> '{drop.GCType}'");
                    swapped++;
                    continue;
                }

                // Pattern C: any other "potion" item that might be a minor we don't
                // recognize - just log so we can add a swap rule next round.
                if (lc.Contains("potion"))
                {
                    Debug.LogError($"[LOOT-MEMBER]   POTION NOT MATCHED: '{gc}' (need a swap rule for this)");
                }
            }
            Debug.LogError($"[LOOT-MEMBER] {who}: {swapped} swap(s) total");
        }

        /// <summary>
        /// Checks player proximity to goto-objective targets. Throttled 1/sec/player.
        ///
        /// Covers the case where a goto objective targets an entity/waypoint IN the
        /// current zone and the player has to walk up to it (e.g. "Locate Entrance to
        /// Rattle Tooth's Lair" — boss_spawn waypoint in dungeon00_level03, range 200).
        ///
        /// Lookup strategy:
        ///  1. Match the objective Label against _gotoGCByLabel (from Q*.gc) to get
        ///     authoritative TargetZoneName / TargetEntityName / Range.
        ///  2. If the player is in TargetZoneName, check distance to a waypoint named
        ///     TargetEntityName — complete if within Range.
        ///  3. Fallback: legacy portal-proximity path for objectives without GC data.
        /// </summary>
        private void CheckGotoProximity(RRConnection conn)
        {
            // Throttle: at most once per second per connection
            int connKey = conn.ConnId;
            float now = Time.time;
            if (_gotoNextCheckTime.TryGetValue(connKey, out float next) && now < next)
                return;
            _gotoNextCheckTime[connKey] = now + 1.0f;

            string connId = conn.ConnId.ToString();
            var questState = QuestManager.Instance.GetPlayerState(connId);
            if (questState == null) return;

            // Quick bail: any incomplete goto objectives at all?
            bool hasGoto = false;
            foreach (var quest in questState.ActiveQuests)
            {
                foreach (var obj in quest.Objectives)
                {
                    if (!obj.IsComplete && obj.Type != null &&
                        obj.Type.Equals("goto", StringComparison.OrdinalIgnoreCase))
                    { hasGoto = true; break; }
                }
                if (hasGoto) break;
            }
            if (!hasGoto) return;

            string curZone = conn.CurrentZoneName;
            if (string.IsNullOrEmpty(curZone)) return;

            float px = conn.PlayerPosX;
            float py = conn.PlayerPosY;

            foreach (var quest in questState.ActiveQuests)
            {
                foreach (var obj in quest.Objectives)
                {
                    if (obj.IsComplete) continue;
                    if (obj.Type == null || !obj.Type.Equals("goto", StringComparison.OrdinalIgnoreCase)) continue;

                    // ── Path 1: GC-data-driven proximity ──
                    if (!string.IsNullOrEmpty(obj.Label) &&
                        _gotoGCByLabel.TryGetValue(obj.Label, out var gc))
                    {
                        // Must be in the right zone (prefix match so child zones like
                        // dungeon00_level03_boss count as being "in" dungeon00_level03).
                        if (!string.IsNullOrEmpty(gc.TargetZone) &&
                            !curZone.StartsWith(gc.TargetZone, StringComparison.OrdinalIgnoreCase))
                            continue;

                        if (!string.IsNullOrEmpty(gc.TargetEntity))
                        {
                            int rng = gc.Range > 0 ? gc.Range : 100;

                            // Step A: look for the waypoint by name in the CURRENT zone.
                            // Fires when the player is physically next to a named
                            // waypoint (e.g. inside dungeon00_level03_boss next to
                            // the boss_spawn waypoint).
                            var wps = DatabaseLoader.GetWaypointsForZone(curZone);
                            if (wps != null)
                            {
                                foreach (var wp in wps)
                                {
                                    if (!wp.name.Equals(gc.TargetEntity, StringComparison.OrdinalIgnoreCase))
                                        continue;
                                    float dx = px - wp.posX;
                                    float dy = py - wp.posY;
                                    float dist = (float)System.Math.Sqrt(dx * dx + dy * dy);
                                    if (dist <= rng)
                                    {
                                        Debug.LogError($"[GOTO-PROXIMITY] ✅ Waypoint match: player ({px:F0},{py:F0}) within {dist:F0} of '{wp.name}' in {curZone} (range={rng}) — completing '{obj.Label}'");
                                        CompleteGotoObjective(conn, quest, obj);
                                        return;
                                    }
                                }
                            }

                            // Step B: PORTAL fallback. Fires when the player is near a
                            // portal in the current zone whose TARGET zone contains a
                            // waypoint with the name we're looking for. This handles
                            // the "Find Entrance to Rattle Tooth's Lair" case:
                            // boss_spawn waypoint lives inside dungeon00_level03_boss,
                            // but the quest should tick when the player walks up to
                            // the entrance PORTAL in dungeon00_level03 — no need to
                            // actually step through.
                            var portalsStepB = DatabaseLoader.GetPortalsForZone(curZone);
                            if (portalsStepB != null)
                            {
                                foreach (var portal in portalsStepB)
                                {
                                    if (string.IsNullOrEmpty(portal.targetZone)) continue;
                                    var targetWps = DatabaseLoader.GetWaypointsForZone(portal.targetZone);
                                    if (targetWps == null) continue;

                                    bool targetHasEntity = false;
                                    foreach (var wp in targetWps)
                                        if (wp.name.Equals(gc.TargetEntity, StringComparison.OrdinalIgnoreCase))
                                        { targetHasEntity = true; break; }
                                    if (!targetHasEntity) continue;

                                    float dx = px - portal.posX;
                                    float dy = py - portal.posY;
                                    float dist = (float)System.Math.Sqrt(dx * dx + dy * dy);
                                    if (dist <= rng)
                                    {
                                        Debug.LogError($"[GOTO-PROXIMITY] ✅ Portal match: player ({px:F0},{py:F0}) within {dist:F0} of portal '{portal.name}'→{portal.targetZone} (range={rng}) — completing '{obj.Label}'");
                                        CompleteGotoObjective(conn, quest, obj);
                                        return;
                                    }
                                }
                            }
                        }
                        // No entity → zone-entry hook handles it
                        continue;
                    }

                    // ── Path 2: Legacy portal-proximity (no GC match or DB target only) ──
                    if (string.IsNullOrEmpty(obj.Target)) continue;
                    var portals = DatabaseLoader.GetPortalsForZone(curZone);
                    if (portals == null || portals.Count == 0) continue;

                    foreach (var portal in portals)
                    {
                        if (string.IsNullOrEmpty(portal.targetZone)) continue;

                        var targetWaypoints = DatabaseLoader.GetWaypointsForZone(portal.targetZone);
                        if (targetWaypoints == null) continue;

                        bool waypointMatch = false;
                        foreach (var wp in targetWaypoints)
                            if (wp.name.Equals(obj.Target, StringComparison.OrdinalIgnoreCase))
                            { waypointMatch = true; break; }
                        if (!waypointMatch) continue;

                        float dx = px - portal.posX;
                        float dy = py - portal.posY;
                        float dist = (float)System.Math.Sqrt(dx * dx + dy * dy);
                        float triggerRange = System.Math.Max(portal.width, portal.height);
                        if (triggerRange < 100) triggerRange = 100;

                        if (dist <= triggerRange)
                        {
                            Debug.LogError($"[GOTO-PROXIMITY] ✅ Portal path: player at ({px:F0},{py:F0}) within {dist:F0} of portal '{portal.name}' (range={triggerRange}) — completing '{obj.Label}'");
                            CompleteGotoObjective(conn, quest, obj);
                            return;
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Called when a player enters a new zone (from ChangeZone). Completes any
        /// goto objectives whose TargetZoneName matches the new zone AND have no
        /// TargetEntityName (zone-entry alone is enough). Quests with an entity get
        /// handled by CheckGotoProximity on the next tick.
        /// </summary>
        private void CompleteGotoObjectivesOnZoneEntry(RRConnection conn)
        {
            string connId = conn.ConnId.ToString();
            var questState = QuestManager.Instance.GetPlayerState(connId);
            if (questState == null) return;

            string curZone = conn.CurrentZoneName;
            if (string.IsNullOrEmpty(curZone)) return;

            bool anyCompleted = false;
            foreach (var quest in questState.ActiveQuests)
            {
                foreach (var obj in quest.Objectives)
                {
                    if (obj.IsComplete) continue;
                    if (obj.Type == null || !obj.Type.Equals("goto", StringComparison.OrdinalIgnoreCase)) continue;
                    if (string.IsNullOrEmpty(obj.Label)) continue;

                    if (!_gotoGCByLabel.TryGetValue(obj.Label, out var gc)) continue;
                    if (string.IsNullOrEmpty(gc.TargetZone)) continue;
                    if (!curZone.StartsWith(gc.TargetZone, StringComparison.OrdinalIgnoreCase)) continue; // prefix: _boss/_off child zones

                    // Zone matches. Complete immediately if no entity required.
                    if (string.IsNullOrEmpty(gc.TargetEntity))
                    {
                        Debug.LogError($"[GOTO-ZONE-ENTRY] ✅ Player entered '{curZone}' — completing goto '{obj.Label}' for quest {quest.QuestId}");
                        CompleteGotoObjective(conn, quest, obj);
                        anyCompleted = true;
                    }
                    // Entity required: CheckGotoProximity handles it on next tick.
                }
            }

            if (anyCompleted)
                SavePlayerQuests(conn);
        }

        /// <summary>
        /// Marks a goto objective complete and pushes progress to the client.
        /// Shared by CheckGotoProximity and CompleteGotoObjectivesOnZoneEntry.
        /// </summary>
        private void CompleteGotoObjective(RRConnection conn, ActiveQuest quest, QuestProgress obj)
        {
            obj.Current = obj.Required;
            QuestManager.Instance.SendProgressPacket(conn, quest.InstanceId, quest);
            SavePlayerQuests(conn);
        }


        /// <summary>
        /// Apply quest completion rewards using the original Dungeon Runners formulas
        /// from GlobalKnobs.gc:
        ///   gold = max(1, level × QuestGoldPerLevel × cashReward × (member ? MemberGoldMod : 1))
        ///   xp   = max(1, level × QuestExperiencePerLevel × (expMod/5) × freeMult × diffMult)
        ///   tokens = TokenReward (King's Coin count, spent at relic vendors)
        ///   xp buff = QuestXPBonus modifier (15% EXPMOD, removed on death) if GrantXPBuff
        /// </summary>
        private void ApplyQuestRewards(RRConnection conn, QuestData questData)
        {
            if (questData == null) return;

            // ----- Look up constants from ServerSettings (mirrors GlobalKnobs.gc) -----
            float questGoldPerLevel = ServerSettings.GetFloat("QuestGoldPerLevel", 250f);
            float questXPPerLevel = ServerSettings.GetFloat("QuestExperiencePerLevel", 100f);
            float memberGoldMod = ServerSettings.GetFloat("MemberGoldMod", 1.15f);
            float freePlayerXPMult = ServerSettings.GetFloat("FreePlayerExperienceMult", 0.87f);
            float gcExperienceMod = ServerSettings.GetFloat("gcExperienceMod", 5.0f);

            bool isFree = IsPlayerFree(conn.LoginName);
            int difficulty = GetDifficultyForConn(conn);
            float diffXPMult = GetDifficultyXPMult(difficulty);

            int qLevel = questData.level > 0 ? questData.level : 1;
            float cashMult = questData.cashReward > 0 ? questData.cashReward : 0.5f;

            // ----- Compute gold (matches in-client quest dialog: level × QuestGoldPerLevel × CashReward) -----
            // NO member bonus on quest rewards. The 1.15× MemberGoldMod applies to monster gold drops only.
            // Granting more than the dialog shows causes the "shows 125, gets 144" mismatch.
            uint goldReward = (uint)System.Math.Max(1, System.Math.Round(
                qLevel * questGoldPerLevel * cashMult));

            // ----- XP from quest turn-in: NONE. -----
            // Per RE of all Q*.gc files: zero quests have a RewardExperience field.
            // Quests grant XP ONLY indirectly via the QuestXPBonus AttributeModifier
            // ("15% More Cowbell" buff) when GrantXPBuff=true. The buff boosts XP from
            // KILLS until death. See block below for the buff dispatch.
            uint xpReward = 0;

            int tokenReward = questData.tokenReward;

            Debug.LogError($"[QUEST-REWARDS] {questData.id} (L{qLevel}) → " +
                           $"{goldReward} gold, {xpReward} XP, {tokenReward} King's Coin(s)" +
                           $" [free={isFree}, cash×{cashMult}, diff×{diffXPMult}, xpBuff={questData.grantXPBuff}]");

            // ----- Apply gold -----
            if (goldReward > 0 && _selectedCharacter.TryGetValue(conn.LoginName, out var rewardGcObj))
            {
                var rewardChar = DungeonRunners.Database.CharacterRepository.GetCharacter(rewardGcObj.Id);
                if (rewardChar != null)
                {
                    rewardChar.gold += goldReward;
                    DungeonRunners.Database.CharacterRepository.SaveCharacter(rewardChar);
                }
                if (conn.UnitContainerId != 0)
                {
                    var goldPkt = new LEWriter();
                    goldPkt.WriteByte(0x07);
                    goldPkt.WriteByte(0x35);
                    goldPkt.WriteUInt16(conn.UnitContainerId);
                    goldPkt.WriteByte(0x20);           // AddCurrency
                    goldPkt.WriteUInt32(goldReward);
                    goldPkt.WriteByte(0x00);           // source
                    goldPkt.WriteUInt32(0x00000000);   // entityHandle
                    goldPkt.WriteByte(0x01);           // notifyFlag
                    WritePlayerEntitySynch(conn, goldPkt);
                    goldPkt.WriteByte(0x06);
                    SendToClient(conn, goldPkt.ToArray());
                    Debug.LogError($"[QUEST-REWARDS] 💰 Sent +{goldReward} gold to client");
                }
            }

            // ----- Apply King's Coin reward as inventory items (QuestItemPAL.Token) -----
            // Per RE: King's Coins are NOT a separate currency. They are inventory items
            // of type QuestItemPAL.Token (1×1, max stack 100). The bottom-left inventory
            // counter is computed client-side via Inventory::getItemCountByType("QuestItemPAL.Token").
            if (tokenReward > 0)
            {
                GiveStackedItem(conn, "QuestItemPAL.Token", tokenReward, 100);
            }

            // ----- XP from quest turn-in is NONE. The buff below is the only quest XP. -----

            // ----- Apply XP buff if quest has GrantXPBuff -----
            if (questData.grantXPBuff)
            {
                SendQuestXPBonusModifier(conn);
            }

            // ----- Reward items via RewardItemGenerator -----
            if (!string.IsNullOrEmpty(questData.rewardItemGenerator) && questData.numRewardItems > 0)
            {
                Debug.LogError($"[QUEST-REWARDS] 📦 Rolling {questData.numRewardItems}× from {questData.rewardItemGenerator}");
                string gen = questData.rewardItemGenerator;
                string genLower = gen.ToLowerInvariant();

                string[] rewardItems = null;

                if (gen.IndexOf("Ring", StringComparison.OrdinalIgnoreCase) >= 0 &&
                    gen.IndexOf("SuperiorJewelry", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    rewardItems = new[] {
                        "ringpal.ring1", "ringpal.ring2", "ringpal.ring3",
                        "ringpal.ring4", "ringpal.ring5", "ringpal.ring6",
                        "ringpal.ring7", "ringpal.ring8", "ringpal.ring9"
                    };
                }
                else if (gen.IndexOf("Amulet", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    rewardItems = new[] {
                        "amuletpal.amulet1", "amuletpal.amulet2", "amuletpal.amulet3",
                        "amuletpal.amulet4", "amuletpal.amulet5", "amuletpal.amulet6"
                    };
                }
                else if (string.Equals(gen, "FreePotionIG", StringComparison.OrdinalIgnoreCase))
                {
                    rewardItems = new[] { "potionpal.healthpotion_noob" };
                }
                else if (string.Equals(gen, "NormalPotionIG", StringComparison.OrdinalIgnoreCase))
                {
                    rewardItems = new[] { "potionpal.healthpotion_itempack", "potionpal.manapotion_itempack" };
                }

                if (rewardItems != null)
                {
                    PlayerState rewardPS = GetPlayerState(conn.ConnId.ToString());
                    int pLvl = rewardPS?.Level ?? 1;

                    for (int ri = 0; ri < questData.numRewardItems; ri++)
                    {
                        int idx = Math.Min(pLvl / 3, rewardItems.Length - 1);
                        string gcType = rewardItems[idx];
                        GiveStackedItem(conn, gcType, 1);
                        Debug.LogError($"[QUEST-REWARDS] 📦 Gave reward to inventory: {gcType} (Level={pLvl})");
                    }
                }
                else
                {
                    // Fallback: generator name may BE the item gcType directly.
                    // DB has: QuestItemPAL.D15Q08_a2, keyig.D08_Q05_1_Key, Dungeon01_ItemIG.Entry4
                    string directGcType = gen;

                    if (genLower.StartsWith("keyig."))
                    {
                        directGcType = "keypal." + gen.Substring(6);
                    }
                    else if (genLower.StartsWith("dungeon01_itemig"))
                    {
                        string[] d01Items = new[] {
                            "dungeon01itempal.d01_item_01", "dungeon01itempal.d01_item_02",
                            "dungeon01itempal.d01_item_03", "dungeon01itempal.d01_key_01"
                        };
                        int entryNum = 0;
                        var entryMatch = System.Text.RegularExpressions.Regex.Match(gen, @"Entry(\d+)", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
                        if (entryMatch.Success) entryNum = int.Parse(entryMatch.Groups[1].Value) - 1;
                        entryNum = Math.Max(0, Math.Min(entryNum, d01Items.Length - 1));
                        directGcType = d01Items[entryNum];
                    }

                    Debug.LogError($"[QUEST-REWARDS] 📦 Direct item give: {gen} → {directGcType} ×{questData.numRewardItems}");
                    GiveStackedItem(conn, directGcType, questData.numRewardItems);
                }
            }
        }

        /// <summary>
        /// Send the QuestXPBonus modifier (15% EXPMOD buff, removed on death).
        /// Same packet pattern as SendFreePlayerModifier — both are AttributeModifiers.
        /// GC type: quests.base.QuestXPBonus, Label: "Quest Reward: 15% More Cowbell".
        /// </summary>
        public void SendQuestXPBonusModifier(RRConnection conn)
        {
            if (conn.ModifiersId == 0)
            {
                Debug.LogError("[QUEST-XP-BUFF] Cannot send QuestXPBonus — ModifiersId not set");
                return;
            }

            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x35);              // ComponentUpdate
            writer.WriteUInt16((ushort)conn.ModifiersId);
            writer.WriteByte(0x00);              // processAddModifier type
            WriteGCType(writer, "quests.base.QuestXPBonus", preserveCase: true);
            // Modifier::readData — 14 bytes (TTD-proven @ 0x4FF390):
            writer.WriteUInt32(2);               // [+0x78] ID (must differ from FreePlayerExperienceModifier=1)
            writer.WriteByte(0);                 // [+0x86] Level
            writer.WriteUInt32(0);               // [+0x80] PowerLevel
            writer.WriteUInt32(0x00000000);      // [+0x7C] Duration (0 = until removed by death)
            writer.WriteByte(0x01);              // [+0x87] SourceIsSelf
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[QUEST-XP-BUFF] ⭐ Sent QuestXPBonus modifier (+15% EXPMOD)");

            // Track the buff so it persists across zone transitions.
            // ResendAllModifiers() is called after every zone change and will re-apply it.
            TrackModifierSent(conn.LoginName, "quests.base.QuestXPBonus", 2,
                level: 0, powerLevel: 0, duration: 0, sourceIsSelf: 1);
            Debug.LogError($"[QUEST-XP-BUFF] 📌 Tracked for zone-change persistence");
        }

        /// <summary>
        /// Send the ZoneSpawnInvulnerabilityModifier — brief immunity to damage
        /// applied each time the player enters a new zone, removed on native
        /// RemoveOnAction events. Mirrors the binary's ZoneSpawnInvulnerability
        /// behavior — "prepare yourself for battle" buff.
        /// GC type: ZoneSpawnInvulnerabilityModifier.
        /// </summary>
        public void SendZoneSpawnInvulnerability(RRConnection conn)
        {
            if (!ShouldSendZoneSpawnInvulnerability(conn))
            {
                ClearZoneSpawnInvulnerability(conn, "ZONE-SKIP");
                Debug.LogError($"[ZONE-INVULN] Skipped ZoneSpawnInvulnerability for {conn?.LoginName ?? "<null>"} (zone={conn?.CurrentZoneName ?? ""})");
                return;
            }

            if (conn.ModifiersId == 0)
            {
                Debug.LogError("[ZONE-INVULN] Cannot send ZoneSpawnInvulnerability — ModifiersId not set");
                return;
            }

            SetZoneSpawnInvulnerability(conn);
            var writer = new LEWriter();
            writer.WriteByte(0x07);              // BeginStream
            writer.WriteByte(0x35);              // ComponentUpdate
            writer.WriteUInt16((ushort)conn.ModifiersId);
            writer.WriteByte(0x00);              // processAddModifier type
            WriteGCType(writer, "avatar.base.ZoneSpawnInvulnerabilityModifier", preserveCase: true);
            // Modifier::readData — 14 bytes (TTD-proven @ 0x4FF390):
            writer.WriteUInt32(3);               // [+0x78] ID (1=FreePlayer, 2=QuestXPBonus, 3=ZoneSpawnInvuln)
            writer.WriteByte(0);                 // [+0x86] Level
            writer.WriteUInt32(0);               // [+0x80] PowerLevel
            writer.WriteUInt32(ZoneSpawnInvulnerabilityDuration);            // [+0x7C] Duration (from .gc file)
            writer.WriteByte(0x01);              // [+0x87] SourceIsSelf
            WritePlayerEntitySynch(conn, writer);
            writer.WriteByte(0x06);              // EndStream

            SendCompressedA(conn, 0x01, 0x0F, writer.ToArray());
            Debug.LogError($"[ZONE-INVULN] Sent ZoneSpawnInvulnerability for {conn.LoginName} (zone={conn.CurrentZoneName})");
            // NOT tracked for persistence — must be re-applied on every zone change.
        }

        private const uint ZoneSpawnInvulnerabilityDuration = 1800;
        private const float ZoneSpawnInvulnerabilityTicksPerSecond = 60f;
        private const float ZoneSpawnInvulnerabilityAddDelay = 0.2f;
        private const float ZoneSpawnInvulnerabilityMoveClearDelay = 0.75f;

        private IEnumerator SendZoneSpawnInvulnerabilityAfterDelay(RRConnection conn, float delay)
        {
            if (delay > 0f)
                yield return new WaitForSeconds(delay);
            if (conn == null || !conn.IsConnected || !conn.IsSpawned) yield break;
            SendZoneSpawnInvulnerability(conn);
        }

        private void SetZoneSpawnInvulnerability(RRConnection conn)
        {
            if (conn == null) return;
            conn.ZoneSpawnInvulnerabilityActive = true;
            conn.ZoneSpawnInvulnerabilityExpiresAt = Time.time + ZoneSpawnInvulnerabilityDuration / ZoneSpawnInvulnerabilityTicksPerSecond;
            conn.ZoneSpawnInvulnerabilitySentAt = Time.time;
            conn.ZoneSpawnInvulnerabilityClearFrame = -1;
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            if (state != null)
                state.IsZoneSpawnDamageImmune = true;
            Debug.LogError($"[ZONE-INVULN] Server immunity active for {conn.LoginName} until={conn.ZoneSpawnInvulnerabilityExpiresAt:F3}");
        }

        private void RefreshZoneSpawnInvulnerability(RRConnection conn)
        {
            if (conn == null || !conn.ZoneSpawnInvulnerabilityActive) return;
            if (conn.ZoneSpawnInvulnerabilityExpiresAt > 0f && Time.time >= conn.ZoneSpawnInvulnerabilityExpiresAt)
                ClearZoneSpawnInvulnerability(conn, "EXPIRE");
        }

        private bool ShouldClearZoneSpawnInvulnerabilityOnMove(RRConnection conn, float x, float y)
        {
            if (conn == null || !conn.ZoneSpawnInvulnerabilityActive) return false;
            if (conn.ZoneSpawnInvulnerabilitySentAt > 0f && Time.time - conn.ZoneSpawnInvulnerabilitySentAt < ZoneSpawnInvulnerabilityMoveClearDelay) return false;
            float dx = x - conn.PlayerPosX;
            float dy = y - conn.PlayerPosY;
            return dx * dx + dy * dy >= 4f;
        }

        private bool IsZoneSpawnInvulnerabilityBlockingCombat(RRConnection conn)
        {
            if (conn == null) return false;
            RefreshZoneSpawnInvulnerability(conn);
            return conn.ZoneSpawnInvulnerabilityActive || conn.ZoneSpawnInvulnerabilityClearFrame == Time.frameCount;
        }

        private void ClearZoneSpawnInvulnerability(RRConnection conn, string reason)
        {
            if (conn == null) return;
            PlayerState state = GetPlayerState(conn.ConnId.ToString());
            bool had = conn.ZoneSpawnInvulnerabilityActive || (state != null && state.IsZoneSpawnDamageImmune);
            if (!had) return;
            conn.ZoneSpawnInvulnerabilityActive = false;
            conn.ZoneSpawnInvulnerabilityExpiresAt = 0f;
            conn.ZoneSpawnInvulnerabilitySentAt = 0f;
            conn.ZoneSpawnInvulnerabilityClearFrame = Time.frameCount;
            if (state != null)
                state.IsZoneSpawnDamageImmune = false;
            Debug.LogError($"[ZONE-INVULN] Cleared server immunity for {conn.LoginName} reason={reason}");
        }

        private bool ShouldSendZoneSpawnInvulnerability(RRConnection conn)
        {
            if (conn == null) return false;

            string zoneName = conn.CurrentZoneName;
            if (string.IsNullOrWhiteSpace(zoneName) && conn.CurrentZoneId != 0 && _zones.TryGetValue(conn.CurrentZoneId, out Zone zone))
                zoneName = zone.name;

            return ZoneAllowsSpawnInvulnerability(zoneName);
        }

        private static bool ZoneAllowsSpawnInvulnerability(string zoneName)
        {
            zoneName = (zoneName ?? "").Trim().ToLowerInvariant();
            if (zoneName.Length == 0) return false;

            if (zoneName == "tutorial") return false;
            if (zoneName == "world.tutorial") return false;
            if (zoneName == "town") return false;
            if (zoneName == "world.town") return false;
            if (zoneName == "thehub") return false;
            if (zoneName == "world.thehub") return false;
            if (zoneName == "pvp_start") return false;
            if (zoneName == "pvp_hub") return false;
            if (zoneName.StartsWith("town")) return false;
            if (zoneName.StartsWith("world.town")) return false;
            if (zoneName.Contains("hub")) return false;

            if (zoneName == "amazon_dungeon") return true;
            if (zoneName.StartsWith("dungeon")) return true;
            if (zoneName.StartsWith("world.dungeon")) return true;
            if (zoneName.StartsWith("d0")) return true;
            if (zoneName.StartsWith("d1")) return true;
            if (zoneName.StartsWith("elite")) return true;
            if (zoneName.StartsWith("epic")) return true;
            if (zoneName.StartsWith("squeakeasy")) return true;
            if (zoneName.StartsWith("deathmatch")) return true;
            if (zoneName.StartsWith("pvpgroup")) return true;
            if (zoneName.StartsWith("pvpduel")) return true;

            return false;
        }

        // Admin "CompleteQuest <instanceId>" cheat handler.
        // Wired up in SetServerCallbacks; called by AdminCommandHandler when the client
        // sends the "CompleteQuest %u" string on channel 9 (binary: 0x46bbb0).
        // Mirrors the regular turn-in flow at the 0x05 turn-in handler so it produces
        // exactly the same client-visible result: items removed, quest removed from log,
        // rewards (XP/gold) applied, NPC markers refreshed.
        private void AdminCompleteQuest(RRConnection conn, uint instanceId)
        {
            try
            {
                var completingQuest = QuestManager.Instance.GetQuestByInstanceId(conn.ConnId.ToString(), instanceId);
                if (completingQuest == null)
                {
                    Debug.LogError($"[ADMIN-COMPLETEQUEST] No active quest with instanceId={instanceId}");
                    return;
                }

                Debug.LogError($"[ADMIN-COMPLETEQUEST] Completing {completingQuest.QuestId} (instanceId={instanceId})");

                QuestData completedQuestData = DatabaseLoader.Quests
                    .FirstOrDefault(q => q.id.Equals(completingQuest.QuestId, StringComparison.OrdinalIgnoreCase));

                // Mark all objectives complete in case anything down the line checks.
                if (completingQuest.Objectives != null)
                {
                    foreach (var obj in completingQuest.Objectives)
                    {
                        if (obj.Required > 0 && obj.Current < obj.Required)
                            obj.Current = obj.Required;
                    }
                }

                RemoveQuestItemsFromInventory(conn, completingQuest);
                QuestManager.Instance.HandleTurnInConfirmed(conn, instanceId);
                SavePlayerQuests(conn);
                ApplyQuestRewards(conn, completedQuestData);

                Debug.LogError($"[ADMIN-COMPLETEQUEST] Done");
            }
            catch (Exception ex)
            {
                Debug.LogError($"[ADMIN-COMPLETEQUEST] EXCEPTION: {ex.GetType().Name}: {ex.Message}\n{ex.StackTrace}");
            }
        }

        private void SavePlayerQuests(RRConnection conn)
        {
            string connId = conn.ConnId.ToString();
            if (!_selectedCharacter.ContainsKey(conn.LoginName)) return;
            var savedChar = CharacterRepository.GetCharacter(_selectedCharacter[conn.LoginName].Id);
            if (savedChar == null) return;

            var questState = QuestManager.Instance.GetPlayerState(connId);
            if (questState == null) return;

            // Save active quests
            savedChar.activeQuests = questState.ActiveQuests.Select(q => new SavedQuest
            {
                questId = q.QuestId,
                questGiverId = q.QuestGiverId,
                acceptedAt = q.AcceptedAt.ToString("o"),
                objectives = q.Objectives.Select(o => new SavedQuestObjective
                {
                    objectiveName = o.ObjectiveName,
                    type = o.Type,
                    target = o.Target,
                    label = o.Label,
                    required = o.Required,
                    current = o.Current
                }).ToList()
            }).ToList();

            // Save completed quests
            savedChar.completedQuests = new List<string>(questState.CompletedQuests);

            // Save unlocked checkpoints
            savedChar.unlockedCheckpoints = new List<string>(questState.UnlockedCheckpoints);

            savedChar.currentZoneName = conn.CurrentZoneName ?? "tutorial";
            savedChar.zoneId = (int)conn.CurrentZoneId;
            CharacterRepository.SaveCharacter(savedChar);
            Debug.LogError($"[SAVE] Saved {savedChar.activeQuests.Count} active, {savedChar.completedQuests.Count} completed quests for {conn.LoginName}");
        }

        /// <summary>
        /// Called by MerchantManager (or item pickup) when a player receives an item,
        /// so QuestManager can update any 'item' type objectives and refresh NPC markers.
        /// </summary>
        public void NotifyQuestItemAcquired(RRConnection conn, string itemGcType)
        {
            if (conn == null || string.IsNullOrEmpty(itemGcType)) return;
            var updates = QuestManager.Instance.OnItemPickedUp(conn, itemGcType);
            if (updates != null && updates.Count > 0)
            {
                Debug.LogError($"[QUEST-ITEM] Item '{itemGcType}' updated {updates.Count} quest objective(s) for {conn.LoginName}");
                SavePlayerQuests(conn);
                // NOTE: Do NOT call SendAvailableQuestUpdateForZone here.
                // The completion flag packet (questSubmsg=0) in SendProgressPacket already
                // tells the client to show yellow ? on the turn-in NPC.
                // Calling SendAvailableQuestUpdateForZone here re-sends the available list
                // which causes Liz Beth to show the quest twice (both ? and !).
            }
        }

        private void SavePlayerLevel(RRConnection conn)
        {
            string connId = conn.ConnId.ToString();
            if (!_selectedCharacter.ContainsKey(conn.LoginName))
            {
                Debug.LogError($"[SAVE] SKIP: No selected character for {conn.LoginName}");
                return;
            }
            var savedChar = CharacterRepository.GetCharacter(_selectedCharacter[conn.LoginName].Id);
            if (savedChar == null)
            {
                Debug.LogError($"[SAVE] SKIP: Character not found for ID={_selectedCharacter[conn.LoginName].Id}");
                return;
            }

            PlayerState playerState = GetPlayerState(connId);
            if (playerState == null)
            {
                Debug.LogError($"[SAVE] SKIP: No PlayerState for {connId}");
                return;
            }

            // Don't overwrite saved progress with a fresh/default PlayerState.
            // Catches any path where SavePlayerLevel fires before playerState has been
            // populated from the DB (e.g. auto-save timer racing the spawn handler).
            // Also protects Level 1 characters that have XP > 0 in DB.
            if (playerState.Level <= 1 && playerState.Experience == 0
                && (savedChar.level > 1 || savedChar.experience > 0))
            {
                Debug.LogError($"[SAVE] SKIPPED - playerState looks uninitialized; would wipe DB lvl={savedChar.level} xp={savedChar.experience} for {conn.LoginName}");
                return;
            }

            savedChar.level = (byte)playerState.Level;
            savedChar.experience = playerState.Experience;
            savedChar.currentHP = playerState.CurrentHPWire;
            savedChar.currentMana = playerState.CurrentManaWire;
            savedChar.currentZoneName = conn.CurrentZoneName ?? "tutorial";
            savedChar.zoneId = (int)conn.CurrentZoneId;

            // Character stats from equipment
            savedChar.maxHP = (int)(playerState.MaxHPWire / 256);
            savedChar.maxMana = (int)(playerState.MaxManaWire / 256);
            // Equipment bonuses are transient — do NOT overwrite allocated stat points
            // savedChar.statStrength/Agility/Intellect/Endurance hold ALLOCATED points only

            // Persist skill levels
            if (_playerSkillLevels.TryGetValue(connId, out var skillLevels))
            {
                // Only save full GC class keys (not short name duplicates)
                foreach (var kvp in skillLevels)
                {
                    if (kvp.Key.Contains("."))  // Full GC class like "skills.generic.PoisonBlastRadius"
                        savedChar.SetSkillLevel(kvp.Key, kvp.Value);
                }
            }

            CharacterRepository.SaveCharacter(savedChar);
            Debug.LogError($"[SAVE] ✅ Level={savedChar.level} XP={savedChar.experience} HP={savedChar.currentHP / 256}/{savedChar.maxHP} Mana={savedChar.currentMana / 256}/{savedChar.maxMana} for {conn.LoginName}");
        }

        public (GCObject item, byte x, byte y)? GetInventoryItemBySlot(string connId, uint slotIndex, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (_playerInventoryItems.ContainsKey(key) && _playerInventoryItems[key].ContainsKey(slotIndex))
            {
                return _playerInventoryItems[key][slotIndex];
            }
            Debug.LogError($"[INV-TRACK] No item at slot {slotIndex} in container 0x{containerId:X2}");
            return null;
        }

        public void RemoveInventoryItemBySlot(string connId, uint slotIndex, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (_playerInventoryItems.ContainsKey(key) && _playerInventoryItems[key].ContainsKey(slotIndex))
            {
                _playerInventoryItems[key].Remove(slotIndex);
                Debug.LogError($"[INV-TRACK] Removed item at slot {slotIndex} in container 0x{containerId:X2}");
            }
        }
        public Dictionary<uint, (GCObject item, byte x, byte y)> GetAllInventoryItems(string connId, byte containerId = 0x0B)
        {
            string key = InvKey(connId, containerId);
            if (_playerInventoryItems.ContainsKey(key))
                return _playerInventoryItems[key];
            return null;
        }

        // Pickup packets carry only a slot index, not a container ID. This searches
        // main inventory first, then each bank page. Returns the containerId where
        // the slot lives, or null if no container has it.
        public byte? FindContainerForSlot(string connId, uint slotIndex)
        {
            if (_playerInventoryItems.ContainsKey(connId) && _playerInventoryItems[connId].ContainsKey(slotIndex))
                return 0x0B;
            byte[] bankIds = { 0x0C, 0x0E, 0x0F, 0x10, 0x11, 0x12, 0x13 };
            foreach (byte cid in bankIds)
            {
                string key = InvKey(connId, cid);
                if (_playerInventoryItems.ContainsKey(key) && _playerInventoryItems[key].ContainsKey(slotIndex))
                    return cid;
            }
            return null;
        }

        public GCObject GetEquippedItem(string connId, uint slot)
        {
            Debug.LogError($"[GET-EQUIP] Looking for Player {connId} slot {slot}");

            if (!_playerEquippedItems.ContainsKey(connId))
            {
                Debug.LogError($"[GET-EQUIP] ❌ Player {connId} NOT in _playerEquippedItems!");
                Debug.LogError($"[GET-EQUIP] Available players: {string.Join(", ", _playerEquippedItems.Keys)}");
                return null;
            }

            if (!_playerEquippedItems[connId].ContainsKey(slot))
            {
                Debug.LogError($"[GET-EQUIP] ❌ Slot {slot} not found for player {connId}!");
                Debug.LogError($"[GET-EQUIP] Available slots: {string.Join(", ", _playerEquippedItems[connId].Keys)}");
                return null;
            }

            GCObject item = _playerEquippedItems[connId][slot];
            Debug.LogError($"[GET-EQUIP] ✅ Found: {item.GCClass}");
            return item;
        }
        public void TrackManipulatorsId(string connId, ushort manipulatorsId)
        {
            _playerManipulatorsIds[connId] = manipulatorsId;
            Debug.LogError($"[MANIPULATORS-TRACK] Player {connId}: Manipulators ID = 0x{manipulatorsId:X4}");
        }

        public ushort GetManipulatorsComponentId(string connId)
        {
            if (_playerManipulatorsIds.ContainsKey(connId))
                return _playerManipulatorsIds[connId];
            Debug.LogError($"[MANIPULATORS] ❌ No ID tracked for player {connId}!");
            return 0;
        }
        public ushort GetUnitContainerComponentId(string connId)
        {
            if (_playerComponentTypes.ContainsKey(connId))
            {
                foreach (var kvp in _playerComponentTypes[connId])
                {
                    if (kvp.Value == "UnitContainer")
                        return kvp.Key;
                }
            }
            Debug.LogError($"[UNITCONTAINER] ❌ No ID tracked for player {connId}!");
            return 0;
        }

        // ═══════════════════════════════════════════════════════════════════════════════
        // DROPPED ITEM TRACKING FOR PICKUP — WITH DB PERSISTENCE
        // ═══════════════════════════════════════════════════════════════════════════════

        public void TrackDroppedItem(ushort entityId, GCObject item, RRConnection conn, int quantity = 1)
        {
            // BUG-FIX (item bleed across sub-levels): previously this used
            // conn.CurrentZoneGcType, but that field collapses every sub-level of a
            // dungeon to the same parent string ("world.dungeon00" for both
            // dungeon00_level01 and dungeon00_level03). Drops in level03 then matched
            // the load query in level01. CurrentZoneName holds the literal map name
            // ("dungeon00_level01") and is the correct identity for drop scoping.
            var info = new DroppedItemInfo
            {
                Item = item,
                DbId = 0,
                Zone = conn.CurrentZoneName ?? "",
                ZoneId = conn.CurrentZoneId,
                InstanceId = conn.InstanceId,
                PosX = conn.PlayerPosX,
                PosY = conn.PlayerPosY,
                PosZ = conn.PlayerPosZ,
                PlayerLevel = GetPlayerState(conn.ConnId.ToString())?.Level ?? 1,
                DroppedBy = conn.LoginName ?? "",
                Quantity = quantity
            };

            // Save to DB
            try
            {
                using (var db = DungeonRunners.Database.GameDatabase.GetConnection())
                {
                    DungeonRunners.Database.GameDatabase.ExecuteNonQuery(db,
                        @"INSERT INTO dropped_items (zone, zone_id, instance_id, gc_class, native_class, pos_x, pos_y, pos_z, player_level, target_slot, preset_scale_mod, dropped_by, rarity, stored_level)
                          VALUES (@zone, @zid, @iid, @gc, @nc, @px, @py, @pz, @pl, @ts, @psm, @db, @rar, @slv)",
                        ("@zone", info.Zone),
                        ("@zid", (int)info.ZoneId),
                        ("@iid", (int)info.InstanceId),
                        ("@gc", item.GCClass),
                        ("@nc", item.NativeClass ?? "Armor"),
                        ("@px", (double)info.PosX),
                        ("@py", (double)info.PosY),
                        ("@pz", (double)info.PosZ),
                        ("@pl", info.PlayerLevel),
                        ("@ts", (int)(item.TargetSlot ?? 0xFFFFFFFF)),
                        ("@psm", item.PresetScaleMod ?? ""),
                        ("@db", info.DroppedBy),
                        ("@rar", item.GetEffectiveRarity()),
                        ("@slv", item.StoredLevel));

                    long dbId = Convert.ToInt64(DungeonRunners.Database.GameDatabase.ExecuteScalar(db, "SELECT last_insert_rowid()"));
                    info.DbId = dbId;
                    _dbIdToEntityId[dbId] = entityId;
                    Debug.LogError($"[DROP-TRACK] Saved to DB: dbId={dbId}, entityId={entityId}, GCClass={item.GCClass}");
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[DROP-TRACK] ❌ DB save failed: {ex.Message}");
            }

            _droppedItems[entityId] = info;
            Debug.LogError($"[DROP-TRACK] Stored dropped item: entityId={entityId}, GCClass={item.GCClass}, zone={info.Zone}, instance={info.InstanceId}");
        }

        public bool IsDroppedItem(ushort entityId)
        {
            return _droppedItems.ContainsKey(entityId);
        }

        public GCObject GetAndRemoveDroppedItem(ushort entityId, out int quantity)
        {
            quantity = 1;
            if (_droppedItems.TryGetValue(entityId, out DroppedItemInfo info))
            {
                _droppedItems.Remove(entityId);
                quantity = info.Quantity;

                // Delete from DB
                if (info.DbId > 0)
                {
                    try
                    {
                        using (var db = DungeonRunners.Database.GameDatabase.GetConnection())
                        {
                            DungeonRunners.Database.GameDatabase.ExecuteNonQuery(db,
                                "DELETE FROM dropped_items WHERE id = @id",
                                ("@id", info.DbId));
                        }
                        _dbIdToEntityId.Remove(info.DbId);
                        Debug.LogError($"[DROP-TRACK] Deleted from DB: dbId={info.DbId}, entityId={entityId}");
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError($"[DROP-TRACK] ❌ DB delete failed: {ex.Message}");
                    }
                }

                return info.Item;
            }
            return null;
        }

        // ═══════════════════════════════════════════════════════════════════════════════
        // LOAD DROPPED ITEMS FOR ZONE — called during zone entry after checkpoints
        // ═══════════════════════════════════════════════════════════════════════════════

        private void SendDroppedItemsForZone(RRConnection conn)
        {
            // Match TrackDroppedItem: scope drops by literal map name, not the parent
            // GC type. See note in TrackDroppedItem for why CurrentZoneGcType is wrong.
            string zone = conn.CurrentZoneName ?? "";
            uint instanceId = conn.InstanceId;

            Debug.LogError($"[DROP-LOAD] Loading dropped items for zone={zone}, instance={instanceId}");

            // Step 1: Re-send items already in memory for this zone (dropped this session by others)
            int inMemoryCount = 0;
            foreach (var kvp in _droppedItems)
            {
                var info = kvp.Value;
                if (info.Zone != zone || info.InstanceId != instanceId) continue;

                // Send spawn packet to this player
                if (info.GoldAmount > 0)
                    SendGoldPileSpawnPacket(conn, kvp.Key, info.PosX, info.PosY, info.PosZ);
                else
                    SendDroppedItemSpawnPacket(conn, kvp.Key, info);
                inMemoryCount++;
            }
            Debug.LogError($"[DROP-LOAD] Re-sent {inMemoryCount} in-memory items");

            // Step 2: Load from DB — items from previous sessions not yet in memory
            int dbCount = 0;
            try
            {
                using (var db = DungeonRunners.Database.GameDatabase.GetConnection())
                using (var reader = DungeonRunners.Database.GameDatabase.ExecuteReader(db,
                    "SELECT id, gc_class, native_class, pos_x, pos_y, pos_z, player_level, target_slot, preset_scale_mod, dropped_by, COALESCE(rarity, -1), COALESCE(stored_level, -1) FROM dropped_items WHERE zone = @zone AND instance_id = @iid",
                    ("@zone", zone), ("@iid", (int)instanceId)))
                {
                    while (reader.Read())
                    {
                        long dbId = reader.GetInt64(0);

                        // Skip if already loaded this session
                        if (_dbIdToEntityId.ContainsKey(dbId)) continue;

                        string gcClass = reader.GetString(1);
                        string nativeClass = reader.GetString(2);
                        float posX = (float)reader.GetDouble(3);
                        float posY = (float)reader.GetDouble(4);
                        float posZ = (float)reader.GetDouble(5);
                        int playerLevel = reader.GetInt32(6);
                        int targetSlotRaw = reader.GetInt32(7);
                        string presetScaleMod = reader.IsDBNull(8) ? "" : reader.GetString(8);
                        string droppedBy = reader.IsDBNull(9) ? "" : reader.GetString(9);
                        int itemRarity = reader.GetInt32(10);
                        int itemStoredLevel = reader.GetInt32(11);

                        // Reconstruct GCObject
                        var item = new GCObject
                        {
                            GCClass = gcClass,
                            NativeClass = nativeClass,
                            StoredRarity = itemRarity,
                            StoredLevel = itemStoredLevel
                        };
                        if (targetSlotRaw >= 0 && targetSlotRaw != -1 && (uint)targetSlotRaw != 0xFFFFFFFF)
                            item.TargetSlot = (uint)targetSlotRaw;
                        if (!string.IsNullOrEmpty(presetScaleMod))
                            item.PresetScaleMod = presetScaleMod;

                        // Assign entity ID and track
                        ushort entityId = GetNextLootEntityId();
                        var info = new DroppedItemInfo
                        {
                            Item = item,
                            DbId = dbId,
                            Zone = zone,
                            ZoneId = conn.CurrentZoneId,
                            InstanceId = instanceId,
                            PosX = posX,
                            PosY = posY,
                            PosZ = posZ,
                            PlayerLevel = playerLevel,
                            DroppedBy = droppedBy
                        };

                        _droppedItems[entityId] = info;
                        _dbIdToEntityId[dbId] = entityId;

                        // Send spawn packet
                        SendDroppedItemSpawnPacket(conn, entityId, info);
                        dbCount++;

                        Debug.LogError($"[DROP-LOAD] Loaded from DB: dbId={dbId}, entityId={entityId}, gc={gcClass}, pos=({posX},{posY},{posZ})");
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[DROP-LOAD] ❌ DB load failed: {ex.Message}");
            }

            Debug.LogError($"[DROP-LOAD] ✅ Zone load complete: {inMemoryCount} in-memory + {dbCount} from DB");
        }

        private void SendDroppedItemSpawnPacket(RRConnection conn, ushort entityId, DroppedItemInfo info)
        {
            int fx = (int)(info.PosX * 256);
            int fy = (int)(info.PosY * 256);
            int fz = (int)(info.PosZ * 256);

            var body = new LEWriter();
            body.WriteByte(0x01);                  // CreateEntity
            body.WriteUInt16(entityId);
            body.WriteByte(0xFF);
            body.WriteCString("itemobject");
            body.WriteByte(0x02);                  // SetPosition
            body.WriteUInt16(entityId);
            body.WriteUInt32(0x00000006);
            body.WriteInt32(fx);
            body.WriteInt32(fy);
            body.WriteInt32(fz);
            body.WriteInt32(0);
            body.WriteByte(0xF7);
            body.WriteUInt16(0x0000);
            body.WriteByte(0x00);
            body.WriteUInt32(0x00000000);
            body.WriteByte(0x00);                  // +0x101 state = 0 triggers updateState state-0 handler -> initState(1) -> FlipController (binary RE: 0x58ac2e)
            body.WriteUInt16(0x2233);
            body.WriteUInt32(0x00000000);
            body.WriteInt32(fx);
            body.WriteInt32(fy);
            body.WriteByte(0xBA);
            info.Item.WriteInitForDroppedItem(body, info.PlayerLevel);

            var chan = new LEWriter();
            chan.WriteByte(0x07);
            chan.WriteBytes(body.ToArray());
            chan.WriteByte(0x06);
            SendToClient(conn, chan.ToArray());
        }

        /// <summary>
        /// Spawn a gold pile entity on the ground. Box.gc → Visual=D3D:GroundObject_Money.
        /// Simple EntityObject — uses minimal consumable-style init (no equipment bytes).
        /// </summary>
        private void SendGoldPileSpawnPacket(RRConnection conn, ushort entityId, float posX, float posY, float posZ)
        {
            int fx = (int)(posX * 256);
            int fy = (int)(posY * 256);
            int fz = (int)(posZ * 256);

            var body = new LEWriter();
            body.WriteByte(0x01);                  // CreateEntity
            body.WriteUInt16(entityId);
            body.WriteByte(0xFF);
            body.WriteCString("itemobject");
            body.WriteByte(0x02);                  // SetPosition
            body.WriteUInt16(entityId);
            body.WriteUInt32(0x00000006);
            body.WriteInt32(fx);
            body.WriteInt32(fy);
            body.WriteInt32(fz);
            body.WriteInt32(0);
            body.WriteByte(0xF7);
            body.WriteUInt16(0x0000);
            body.WriteByte(0x00);
            body.WriteUInt32(0x00000000);
            body.WriteByte(0x00);
            body.WriteUInt16(0x2233);
            body.WriteUInt32(0x00000000);
            body.WriteInt32(fx);
            body.WriteInt32(fy);
            body.WriteByte(0xBA);
            body.WriteByte(0xFF);
            body.WriteCString("questitempal2.ww00_gb01");
            body.WriteUInt32(0);
            body.WriteByte(0x00);
            body.WriteByte(0x00);
            body.WriteByte(0x01);
            body.WriteByte(0x01);
            body.WriteByte(0x00);
            body.WriteByte(0x00);

            var chan = new LEWriter();
            chan.WriteByte(0x07);
            chan.WriteBytes(body.ToArray());
            chan.WriteByte(0x06);
            SendToClient(conn, chan.ToArray());
        }

        // ═══════════════════════════════════════════════════════════════════════════════
        // CLEANUP EXPIRED DROPPED ITEMS — called from Update() timer
        // ═══════════════════════════════════════════════════════════════════════════════

        private void CleanupExpiredDroppedItems()
        {
            // Delete expired rows from DB
            List<long> expiredDbIds = new List<long>();
            try
            {
                using (var db = DungeonRunners.Database.GameDatabase.GetConnection())
                {
                    // First find which IDs are expired
                    using (var reader = DungeonRunners.Database.GameDatabase.ExecuteReader(db,
                        $"SELECT id FROM dropped_items WHERE dropped_at < datetime('now', '-{DROPPED_ITEM_EXPIRE_MINUTES} minutes')"))
                    {
                        while (reader.Read())
                            expiredDbIds.Add(reader.GetInt64(0));
                    }

                    if (expiredDbIds.Count > 0)
                    {
                        // Delete them
                        DungeonRunners.Database.GameDatabase.ExecuteNonQuery(db,
                            $"DELETE FROM dropped_items WHERE dropped_at < datetime('now', '-{DROPPED_ITEM_EXPIRE_MINUTES} minutes')");
                        Debug.LogError($"[DROP-CLEANUP] Deleted {expiredDbIds.Count} expired items from DB");
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"[DROP-CLEANUP] ❌ DB cleanup failed: {ex.Message}");
            }

            // Remove from in-memory tracking and despawn for online players
            foreach (long dbId in expiredDbIds)
            {
                if (_dbIdToEntityId.TryGetValue(dbId, out ushort entityId))
                {
                    if (_droppedItems.TryGetValue(entityId, out DroppedItemInfo info))
                    {
                        // Despawn for all players in this zone
                        foreach (var other in _connections.Values)
                        {
                            if (!other.IsSpawned) continue;
                            if (other.CurrentZoneGcType != info.Zone) continue;
                            if (other.InstanceId != info.InstanceId) continue;
                            SendDespawnEntity(other, entityId);
                        }
                        _droppedItems.Remove(entityId);
                    }
                    _dbIdToEntityId.Remove(dbId);
                }
            }
        }












